insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104760','test','Тест по 7-й смене (меню кухни)','waiter-internship','{"id":"104760","title":"Тест по 7-й смене (меню кухни)","timeLimitSeconds":690,"passCount":23,"questions":[{"id":"104760-1","text":"Как называется тартар из лосося, который подается в вафельном стаканчике?","type":"single","options":["Жадина-говядина","Детям мороженое","Играем в бутылочку?"]},{"id":"104760-2","text":"Что входит в состав салата «Один раз не нисуаз»?","type":"single","options":["Жареные креветки","Маринованный тунец","Копченая индейка"]},{"id":"104760-3","text":"Какой сыр используется в салате «Круэлла-страчателла»?","type":"single","options":["Сыр дор-блю","Сыр гауда","Молодой сыр (страчателла)"]},{"id":"104760-4","text":"Какая граммовка у салата «Шеф развязал»?","type":"single","options":["180 гр","160 гр","200 гр"]},{"id":"104760-5","text":"Какие морепродукты входят в состав супа Том Ям?","type":"single","options":["Только мидии","Креветки, мидии, кальмары, лосось","Только креветки"]},{"id":"104760-6","text":"Какая лапша используется в пасте «Соба с морепродуктами»?","type":"single","options":["Рисовая","Гречневая","Пшеничная"]},{"id":"104760-7","text":"Какой размер у «Клубной пиццы 90-е»?","type":"single","options":["22 см","30 см","33 см"]},{"id":"104760-8","text":"В состав какого блюда входит паштет из шпрот?","type":"single","options":["Закуска 90-е","Лихие 90-е","Трио брускетт"]},{"id":"104760-9","text":"Под каким названием скрывается турецкая пицца с говядиной?","type":"single","options":["Сам ты — Наташа!","Где фунтик?","Попробуй джага-джага"]},{"id":"104760-10","text":"С каким соусом подаются сырные палочки «Палочка выручалочка»?","type":"single","options":["Унаги","Спайси","Сырный"]},{"id":"104760-11","text":"С чем подается теплый салат из щупалец кальмара?","type":"single","options":["С рисом и брокколи","С молодым картофелем и овощами","С макаронами и сыром"]},{"id":"104760-12","text":"В состав салата «Тропикана женщина» входят:","type":"single","options":["Жареные баклажаны и томаты","Теплые креветки, соус из манго, кокосовое молоко и свежие ягоды","Копченая индейка и грейпфрут"]},{"id":"104760-13","text":"Как называются мидии, запеченные с сыром и икрой тобико?","type":"single","options":["Мидии гранд киви","Мидийное место","Мидии по-королевски"]},{"id":"104760-14","text":"Из меню «Малиновых пиджаков»: какие соусы можно выбрать к стейку Пиканья?","type":"single","options":["Мясной, горчичный, грибной","Только грибной и томатный","Только мясной и сырный"]},{"id":"104760-15","text":"С каким гарниром подается стейк лосося?","type":"single","options":["С пюре из брокколи","С отварным рисом","С жареным картофелем"]},{"id":"104760-16","text":"Какой соус используется в салате «Теплый баклажан»?","type":"single","options":["Блю-чиз","Понзу","Цезарь"]},{"id":"104760-17","text":"Какое блюдо скрывается под названием «Но я тебе не дам!»?","type":"single","options":["Салат с ростбифом","Салат с тунцом","Зелёный салат с копчёной индейкой, авокадо и грейпфрутом"]},{"id":"104760-18","text":"Под каким названием скрывается запечённый багет с пепперони, ветчиной и курицей?","type":"single","options":["Где фунтик?","Попробуй джага-джага","Сам ты — Наташа!"]},{"id":"104760-19","text":"С каким соусом подаются чесночные гренки?","type":"single","options":["Соус спайси","Соус BBQ","Сырный соус"]},{"id":"104760-20","text":"Из чего готовятся «Шары ярости»?","type":"single","options":["Из куриного филе в панировке","Крокеты из снежного краба с сыром и соусом унаги","Из картофеля и грибов"]},{"id":"104760-21","text":"Что подают в блюде с игривым названием «Играем в бутылочку?»?","type":"single","options":["Мидии, запеченные с сыром","Ростбиф, сыр гауда, сыр дор-блю, маслины, креветки, корнишоны и помидоры черри","Свиные ребра с соусом чили"]},{"id":"104760-22","text":"Какие ингредиенты входят в состав тартара из мраморной говядины?","type":"single","options":["Ростбиф, сыр гауда и креветки","Говядина, авокадо и сливочный сыр","Каперсы, горчица и чипсы из батата"]},{"id":"104760-23","text":"С чем подается зеленый салат со слабосоленым лососем?","type":"single","options":["С яйцом пашот и соусом блю-чиз","С грейпфрутом и авокадо","С креветками и мидиями"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104939','test','Тест по 7-й смене (меню бара)','waiter-internship','{"id":"104939","title":"Тест по 7-й смене (меню бара)","timeLimitSeconds":390,"passCount":13,"questions":[{"id":"104939-1","text":"Какая текила на 100% состоит из голубой агавы и стоит 740 ₽?","type":"single","options":["Agavita Blanco","Espolon Reposado","La Pavesa Plata"]},{"id":"104939-2","text":"Какой вкус домашней настойки стоит 340 ₽, в отличие от остальных за 290 ₽?","type":"single","options":["Пряное Яблоко","Малина&Чили","Лимончелло"]},{"id":"104939-3","text":"Сколько стоит бутылка игристого вина Moët & Chandon Brut Imperial?","type":"single","options":["4,900 ₽","21,900 ₽","4,100 ₽"]},{"id":"104939-4","text":"Какое бутылочное пиво является безалкогольным?","type":"single","options":["Corona Extra","Stella Artois","Hoegaarden"]},{"id":"104939-5","text":"Какое розовое вино представлено в бутылках?","type":"single","options":["Vinho Verde Diario Rosado","Cinzano Asti Spumante","Chardonnay Golubitskoe Estate"]},{"id":"104939-6","text":"Какой объём имеет коктейль «Москва Never Sleep»?","type":"single","options":["250 мл","300 мл","330 мл"]},{"id":"104939-7","text":"В каком авторском коктейле подаётся «вкусный домашний мармелад»?","type":"single","options":["Золотая Рыбка","Мальчик Хочет в Тайланд","Ни Фейхоя Себе"]},{"id":"104939-8","text":"Какой виски относится к категории «Бурбон»","type":"single","options":["Jack Daniel''s Old N°7","Bushmills Original","Grants Triple Wood"]},{"id":"104939-9","text":"Какое вино из категории «Красное вино по бутылкам» является самым дорогим?","type":"single","options":["Pinot Noir Bouchard Aine & Fils Grand Conseiller","Chateau Argadens Rouge","Merlot Urban Sun"]},{"id":"104939-10","text":"Какая страна является производителем вина Chenin Blanc KWV?","type":"single","options":["Россия","ЮАР","Чили"]},{"id":"104939-11","text":"Вермут Cinzano какого типа отсутствует в карте?","type":"single","options":["Rosato","Bitter","Bianco"]},{"id":"104939-12","text":"В состав какого коктейля входят абсент и сироп корицы?","type":"single","options":["Моя Бабушка Курит Трубку","Настоящий Полковник","Слово Пацана"]},{"id":"104939-13","text":"Сколько стоит огромная коктельная башня «Шотландия» из 28 шотов?","type":"single","options":["6,100 ₽","5,000 ₽","7,500 ₽"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104160','test','Тест по 8-й смене','waiter-internship','{"id":"104160","title":"Тест по 8-й смене","timeLimitSeconds":150,"passCount":5,"questions":[{"id":"104160-1","text":"Прошло 25 минут, а блюдо еще не готово. Что делать?","type":"single","options":["Предложить гостю скидку без согласования с менеджером","Подойти к раздаче, вежливо уточнить время, затем подойти к гостю и сказать спасибо за ожидание","Кричать на поваров","Сделать вид, что ничего не происходит"]},{"id":"104160-2","text":"В конце смены наставник говорит тебе, что ты забывал убирать пустые тарелки. Твоя реакция?","type":"single","options":["Сказать, что это не моя работа","Внимательно выслушать, запомнить замечание и в следующей смене следить за этим","Обвинить коллег, что они не помогали","Обидеться и уйти"]},{"id":"104160-3","text":"Сегодня ты впервые работаешь с 2–3 своими столами. Какова твоя основная роль?","type":"single","options":["Работать в баре, пока наставник в зале","Просто наблюдать за наставником и ничего не делать","Только подавать блюда, а заказ принимает наставник","Самостоятельно обслуживать столы, наставник рядом и подстраховывает"]},{"id":"104160-4","text":"Гость заказал стейк, который готовится 30 минут. Твои действия?","type":"single","options":["Сразу предупредить: «Стейк удет готов примерно 25–30 минут»","Ничего не говорить, чтобы не расстраивать гостя","Посоветовать выбрать другое блюдо","Сказать, что удет через 10 минут, а потом извиниться"]},{"id":"104160-5","text":"У гостя день рождения, нужно подать торт со свечой. С чего начать?","type":"single","options":["Просто вынести торт и поставить на стол","Попросить гостя самому подойти к бару за тортом","Узнать имя именинника, предупредить наставника и диджея, собрать коллег для поздравления","Громко объявить на весь зал, что у гостя праздник"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104161','test','Тест по 9-й смене','waiter-internship','{"id":"104161","title":"Тест по 9-й смене","timeLimitSeconds":180,"passCount":6,"questions":[{"id":"104161-1","text":"Гость говорит: «Салат пересолен, мне не нравится». Твои первые действия?","type":"single","options":["Предложить скидку 50% прямо сейчас","Забрать салат и унести на кухню","Извиниться, поблагодарить за обратную связь и позвать наставника/менеджера","Сказать, что так и должно быть"]},{"id":"104161-2","text":"Какое правило действует для оплаты счетов со скидкой 20% и выше (например, 50% на день рождения)?","type":"single","options":["Только переводом на карту","Только наличными","Только картой","Можно оплачивать как угодно"]},{"id":"104161-3","text":"Какие проценты начисления бонусов действуют для карты постоянного гостя в зависимости от суммы трат?","type":"single","options":["10%, 15%, 20%","3%, 5%, 7%","5%, 7%, 10%","1%, 2%, 3%"]},{"id":"104161-4","text":"Что нужно проверить на станции официанта в конце смены?","type":"single","options":["Это забота уборщицы, официант не проверяет","Наличие салфеток (бумажных и влажных), соли, перца, текстиля","Только наличие салфеток","Только наличие соли и перца"]},{"id":"104161-5","text":"Где находятся QR-коды для сбора отзывов?","type":"single","options":["Нужно гуглить каждый раз","В рабочем чате «Честный отзыв»","Только у менеджера под роспись","На каждом столе в специальной рамке"]},{"id":"104161-6","text":"Что ты предлагаешь гостю за написанный отзыв?","type":"single","options":["Десерт от шефа","Бесплатный коктейль «Виски-кола»","Скидку 10% на следующий визит","Брендированный мерч"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104181','test','Тест по 10-й смене','waiter-internship','{"id":"104181","title":"Тест по 10-й смене","timeLimitSeconds":150,"passCount":5,"questions":[{"id":"104181-1","text":"Как распределяются обязанности в 10-й смене?","type":"single","options":["Наставник общается с гостями и принимает заказы, стажер выполняет всё остальное","Стажер только наблюдает, наставник делает всё сам","Стажер принимает заказы, наставник только подает","Каждый работает сам по себе, не мешая друг другу"]},{"id":"104181-2","text":"Какая нагрузка считается пиковой и в какое время?","type":"single","options":["Пятница, суббота, воскресенье и праздники с 23:00 до 03:00, может быть 10–20 столов","Каждый день с 00 до 06 часов, нагрузка всегда одинаковая","Будни с 18 до 22 часов, 5–7 столов","Только суббота с 20 до 02 часов, не больше 15 столов"]},{"id":"104181-3","text":"Что происходит со временем ожидания блюд в пиковые часы?","type":"single","options":["Гости всегда ждут ровно 15 минут независимо от загрузки","Оно увеличивается в зависимости от загрузки","Оно сокращается, потому что повара работают быстрее","Оно не меняется, мы всегда готовим одинаково"]},{"id":"104181-4","text":"Как ты должен предупредить гостя о возможной задержке?","type":"single","options":["Сказать, что будет через 5 минут, а потом извиниться","Когда наставник принимает заказ, он предупреждает: «Сейчас пиковое время, ожидание может быть дольше»","Переложить ответственность на поваров","Молчать, чтобы не расстраивать"]},{"id":"104181-5","text":"Что делать, если ты не успеваешь обслуживать свои столы в пик?","type":"single","options":["Бросить всё и уйти на перерыв","Игнорировать некоторые столы","Паниковать и бегать быстрее","Попросить помощи у коллег — это нормально в пиковые часы"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105476','test','Тест по 10-й смене (мини-квиз по вину)','waiter-internship','{"id":"105476","title":"Тест по 10-й смене (мини-квиз по вину)","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"105476-1","text":"Какое красное вино из России (Каберне Совиньон) имеет ноты вишни, сливы, ванили и дуба?","type":"single","options":["Cabernet Golubitskoe Estate","Malbec Tamari","Chianti Sant‘Orsola","Merlot Urban Sun"]},{"id":"105476-2","text":"Какое розовое вино из Португалии имеет полусухой профиль и универсально в гастрономии?","type":"single","options":["Santa Cecillia Semi-Sweet Red","Fiorino D‘Oro Brut","Vinho Verde Diario Rosado","Intermarium Brut"]},{"id":"105476-3","text":"Какое игристое вино производится в России по традиционному методу шампанизации и выдерживается минимум 20 месяцев?","type":"single","options":["Abrau Durso Reserve Brut","Tete de Cheval Golubitskoe Estate","Louis Bouillot Cremant de Bourgogne Grand Reserve Brut","Celebrities Cava Brut"]},{"id":"105476-4","text":"Какое белое вино из Рислинга (Германия) имеет полусухой профиль и подходит к лёгким блюдам?","type":"single","options":["Chenin Blanc KWV","Riesling Peter Mertes","Sauvignon Blanc The Ned","Chardonnay Urban Sun"]},{"id":"105476-5","text":"Какое игристое сладкое вино из Италии (Москато Бьянко) подходит к десертам?","type":"single","options":["Fiorino D‘Oro Brut","Cinzano Asti Spumante","Bruni Prosecco","Cinzano Prosecco"]},{"id":"105476-6","text":"Какое белое вино из Чили (Шардоне) имеет ноты ананаса, персика и ванили?","type":"single","options":["Santa Cecilia Semi-Sweet White","Chardonnay Golubitskoe Estate","Riesling Intermarium","Chardonnay Tarapaca"]},{"id":"105476-7","text":"Какое белое вино из Новой Зеландии (Совиньон Блан) имеет ноты лайма, крыжовника и лемонграсса?","type":"single","options":["Sauvignon Blanc The Ned","Riesling Intermarium","Pinot Grigio Sant‘Orsola","Chardonnay Tarapaca"]},{"id":"105476-8","text":"Какое красное вино из Аргентины (Мальбек) имеет ноты смородины, вишни, сливы, ванили и шоколада?","type":"single","options":["Château Argadens Rouge Bordeaux Supérieur AOC","Tempranillo El Pillo Roble Felix Solis","Cabernet Sauvignon Intermarium","Malbec Tamari"]},{"id":"105476-9","text":"Какое игристое брют из Франции (Бургундия) имеет ноты грейпфрута, яблок и тостов?","type":"single","options":["Moet&Chandon Brut Imperial","Celebrities Cava Brut","Bruni Prosecco Valdobbiadene","Louis Bouillot Cremant de Bourgogne Grand Reserve Brut"]},{"id":"105476-10","text":"Какое красное вино из Франции (Бордо) — купаж Мерло, Каберне Фран и Каберне Совиньон?","type":"single","options":["Cabernet Golubitskoe Estate","Pinot Noir Bouchard Aine&Fils","Merlot Urban Sun","Château Argadens Rouge Bordeaux Supérieur AOC"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104187','test','Тест по 11-й смене','waiter-internship','{"id":"104187","title":"Тест по 11-й смене","timeLimitSeconds":240,"passCount":8,"questions":[{"id":"104187-1","text":"От чего зависит сервировка банкетного стола?","type":"single","options":["От времени года","От предзаказа (какие напитки и блюда заказаны)","От настроения гостей","От количества свободных бокалов в баре"]},{"id":"104187-2","text":"Что обязательно нужно подготовить для банкета заранее?","type":"single","options":["Сменные тарелки, приборы для раскладки, салфетки, нужные бокалы","Только салфетки","Музыкальное сопровождение","Только меню для гостей"]},{"id":"104187-3","text":"Какая последовательность подачи блюд на банкете правильная?","type":"single","options":["Холодные закуски → салаты → горячие закуски → горячие блюда → десерт","Салаты → десерт → горячее → закуски","Горячее → салаты → закуски → десерт","Десерт → горячее → салаты → закуски"]},{"id":"104187-4","text":"Какое блюдо относится к категории «горячие закуски» в нашем банкетном меню?","type":"single","options":["Памела Андерсон","Жюльен из цыплёнка","Оливье по-домашнему","Закуска а-ля 90-е"]},{"id":"104187-5","text":"Кого нужно предупредить перед поздравлением именинника?","type":"single","options":["Никого не нужно предупреждать, подойти самому","Только бармена","Только администратора","Ведущего, кухню и собрать коллег для поздравления"]},{"id":"104187-6","text":"Какие бокалы нужно поставить, если в предзаказе есть игристое вино?","type":"single","options":["Рокс","Флютте","Олд фэшн","Хайбол"]},{"id":"104187-7","text":"Что нужно сделать при порционной раскладке блюда из общей тарелки?","type":"single","options":["Разложить еду руками","Поставить общую тарелку в центр и уйти","Попросить гостей разложить самим","Использовать отдельные приборы для раскладки (ложку и вилку)"]},{"id":"104187-8","text":"Что нужно сделать с десертом для именинника?","type":"single","options":["Принести без согласования с кухней","Пробить в счет гостя","Пробить как комплимент от заведения (десерт дарим бесплатно)","Попросить гостя оплатить отдельно"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104335','test','Тест по 12-й смене','waiter-internship','{"id":"104335","title":"Тест по 12-й смене","timeLimitSeconds":150,"passCount":5,"questions":[{"id":"104335-1","text":"Что нужно контролировать на станции официанта в течение смены?","type":"single","options":["Ничего, это забота уборщицы","Тарелки, приборы, салфетницы (полные и чистые), запас бумажных и влажных салфеток, соль/перец","Только наличие салфеток","Только наличие меню"]},{"id":"104335-2","text":"Что нужно сделать с салфетницами в течение смены?","type":"single","options":["Убрать их со столов, чтобы не мешали","Менять только в конце смены","Протирать и пополнять салфетки, следить, чтобы они были полными и чистыми","Салфетницы не трогать, это делает менеджер"]},{"id":"104335-3","text":"Для чего нужен фотоотчет о закрытии смены?","type":"single","options":["Чтобы отправить поварам","Для личного архива","Чтобы похвастаться в соцсетях","Как доказательство, что зал убран идеально"]},{"id":"104335-4","text":"Во сколько закрывается заведение и до какого времени нужно делать уборку?","type":"single","options":["Закрытие в 4:00, уборка до 5:00","В 7:00 закрытие, можно уходить сразу","В 5:00 закрытие, замывка до 6:00","В 6:00 закрытие, замывка до 6:30–7:00"]},{"id":"104335-5","text":"Что обязательно нужно сделать при закрытии смены (согласно чек-листу)?","type":"single","options":["Протереть столы, стейшены, салфетницы, натереть посуду, нагладить текстиль, сделать фотоотчет, написать ОС","Протереть только столы","Сдать смену менеджеру и сразу уйти","Только выключить свет и уйти"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104336','test','Тест по 12-й смене (Авторские коктейли)','waiter-internship','{"id":"104336","title":"Тест по 12-й смене (Авторские коктейли)","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"104336-1","text":"В состав какого коктейля входят малиновый биттер, сок грейпфрута и маршмеллоу?","type":"single","options":["Ограбление по Итальянски","Укрощение Строптивой","Розовый Фламинго","Ни Фейхоя Себе"]},{"id":"104336-2","text":"Какие ингредиенты входят в состав коктейля «Невозможное Возможно»?","type":"single","options":["Водка Tundra Authentic, пюре маракуйи, ванильный сироп","Джин Green Baboon, апельсиновый ликёр, ананасовый сок","Настойка Ежевика&Можжевельник, ананасовый сок, сироп клубники и бабл гам, сок лимона","Текила La Pavesa Plata, кордиал алоэ с мёдом, пюре крыжовника"]},{"id":"104336-3","text":"В состав какого коктейля входят персиковый ликёр, водка Tundra Authentic и домашний мармелад?","type":"single","options":["Секс в Большом Городе","Золотая Рыбка","Поющие в Крыжовнике","Укрощение Строптивой"]},{"id":"104336-4","text":"Какой коктейль содержит грейпфрутовый кордиал и розовый перец?","type":"single","options":["Мальчик Хочет в Тайланд","Богатые Тоже Платят","Розовый Фламинго","Невозможное Возможно"]},{"id":"104336-5","text":"Какие ингредиенты входят в коктейль «Поющие в Крыжовнике»?","type":"single","options":["Водка Tundra Authentic, игристое вино, пюре маракуйи","Текила La Pavesa Plata, кордиал алоэ с мёдом, сок лимона, пюре крыжовника, яичный белок","Джин Green Baboon, малиновый биттер, сок грейпфрута","Настойка Ежевика&Можжевельник, ананасовый сок, сироп бабл гам"]},{"id":"104336-6","text":"Какой коктейль готовится на основе джина Green Baboon, вермута Cinzano Rosso и карамельных сот?","type":"single","options":["Золотая Рыбка","Розовый Фламинго","Ни Фейхоя Себе","Ограбление по Итальянски"]},{"id":"104336-7","text":"Какой коктейль готовится на основе джина Green Baboon, апельсинового ликёра, биттера, апельсинового и ананасового сока?","type":"single","options":["Невозможное Возможно","Ограбление по Итальянски","Мальчик Хочет в Тайланд","Розовый Фламинго"]},{"id":"104336-8","text":"Какие ингредиенты входят в коктейль «Укрощение Строптивой»?","type":"single","options":["Клубничное пюре, игристое вино","Малиновый биттер, сок грейпфрута, маршмеллоу","Персиковый ликёр, водка Tundra Authentic, мармелад","Текила La Pavesa Plata, кордиал алоэ с мёдом, пюре крыжовника"]},{"id":"104336-9","text":"Какие ингредиенты входят в коктейль «Ни Фейхоя Себе»?","type":"single","options":["Джин Green Baboon, вермут Cinzano Extra Dry, кордиал фейхоа, сироп киви, яблочный и лимонный сок","Текила La Pavesa Plata, грейпфрутовый кордиал, сок лимона, розовый перец","Водка Tundra Authentic, кордиал на чае эрл грей, мармелад","Настойка Ежевика&Можжевельник, ананасовый сок, сироп клубники"]},{"id":"104336-10","text":"Какой коктейль готовится из игристого вина, водки Tundra Authentic и пюре маракуйи?","type":"single","options":["Золотая Рыбка","Богатые Тоже Платят","Секс в Большом Городе","Невозможное Возможно"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104337','test','Тест по 13-й смене','waiter-internship','{"id":"104337","title":"Тест по 13-й смене","timeLimitSeconds":210,"passCount":7,"questions":[{"id":"104337-1","text":"Какой тайминг считается правильным для подачи напитков после принятия заказа?","type":"single","options":["10–15 минут","Когда гость напомнит","3–5 минут","Сразу после горячего"]},{"id":"104337-2","text":"Зачем стажёру проводить мини-инструктаж для другого стажёра?","type":"single","options":["Чтобы лучше запомнить материал и развить лидерские качества","Чтобы наставник отстал","Чтобы показать свою власть","Чтобы отвлечься от работы"]},{"id":"104337-3","text":"Что из перечисленного НЕ является техникой дополнительных продаж (upsell)?","type":"single","options":["«Вам точно понравилось?»","«На десерт сегодня потрясающая \"Памела Андерсон\"»","«Хотите добавить фирменный соус?»","«К вашему вину отлично подойдёт сырное плато»"]},{"id":"104337-4","text":"Что нужно сделать, если горячее блюдо задерживается на кухне?","type":"single","options":["Молчать, чтобы не расстраивать гостя","Обвинить поваров","Предложить скидку без согласования","Подойти и честно сказать: «Блюдо готовится чуть дольше, спасибо за терпение»"]},{"id":"104337-5","text":"Какая техника продаж помогает гостю сделать выбор, а не просто ответить «да» или «нет»?","type":"single","options":["Техника «Золотой треугольник»","Техника «Ограниченное предложение»","Техника «Молчаливый официант»","Техника «Открытые вопросы»"]},{"id":"104337-6","text":"Кого ты обслуживаешь в 13-й смене и почему это важно?","type":"single","options":["Обычных гостей, чтобы потренироваться в скорости","Топ-персонал (менеджеров, управляющих, бар-менеджеров) — они оценят твою готовность к самостоятельной работе","Только своих друзей, чтобы было веселее","Никого, это выходной"]},{"id":"104337-7","text":"Как правильно описать блюдо, чтобы у гостя появилось желание его заказать?","type":"single","options":["«Попробуйте наш стейк из лосося в сливочном соусе с красной икрой — нежнейшее филе, тает во рту, подаётся с пюре из брокколи и свежей спаржей»","«У нас есть рыба»","«Это дорого, но вкусно»","«Как хотите»"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104338','test','Тест по 14-й смене','waiter-internship','{"id":"104338","title":"Тест по 14-й смене","timeLimitSeconds":180,"passCount":6,"questions":[{"id":"104338-1","text":"Что из перечисленного входит в зону твоей ответственности при самостоятельной работе?","type":"single","options":["Всё: встреча, приём заказа, подача, уборка, расчёт, работа с отзывами","Только открытие смены","Только подача блюд","Только приём заказов"]},{"id":"104338-2","text":"Во сколько нужно прийти на смену в будний день согласно чек-листу?","type":"single","options":["16:00","16:45","17:00","17:30"]},{"id":"104338-3","text":"Что нужно проверить на станции официанта перед закрытием смены?","type":"single","options":["Только чистоту столов","Ничего, это забота уборщицы","Только наличие салфеток","Наличие расходников (салфетки, соль/перец, тарелки, приборы) и текстиля на следующую смену"]},{"id":"104338-4","text":"Что обязательно нужно сделать к 17:45 перед открытием зала?","type":"single","options":["Выпить кофе и отдохнуть","Подготовить только бар","Проверить готовность зала, стоп-лист и пойти на общее собрание","Разложить только тарелки"]},{"id":"104338-5","text":"Какой финальный шаг при закрытии смены согласно чек-листу?","type":"single","options":["Сделать фотоотчёт, написать ОС о смене и отчитаться старшему официанту или менеджеру","Выключить свет и закрыть дверь","Просто уйти домой","Оставить посуду на мойку"]},{"id":"104338-6","text":"Как правильно действовать при максимальной загрузке (пиковые часы)?","type":"single","options":["Бегать быстрее, чтобы всё успеть","Просить гостей подождать","Ходить быстро, но плавно, не носить больше трёх тарелок, приоритизировать задачи","Игнорировать часть столов"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('104460','test','Проверка знаний 📝🧠✅','welcome-90','{"id":"104460","title":"Проверка знаний 📝🧠✅","timeLimitSeconds":150,"passCount":5,"questions":[{"id":"104460-1","text":"Какой элемент интерьера сразу погружает гостей в ностальгию?","type":"single","options":["Современные цифровые экраны с абстрактной графикой.","На стенах висят кассеты, плакаты, малиновые пиджаки, олимпийки.","Антикварная мебель в классическом стиле."]},{"id":"104460-2","text":"Наша супер-концепция?","type":"single","options":["Фуд-корт с fast-food из разных стран.","Формат «4 в 1» (бар, дискотека, караоке, ресторан) и атмосфера 90-х.","Премиальный коктейльный бар с тихой джазовой музыкой."]},{"id":"104460-3","text":"Что делать в первый день, если что-то непонятно?","type":"single","options":["Спросить совета у первого попавшегося гостя.","Спрашивать у наставника или менеджера","Делать вид, что всё знаешь, чтобы не показаться некомпетентным."]},{"id":"104460-4","text":"Главное правило общения с гостем?","type":"single","options":["Быть другом: легко, с улыбкой, с искрой.","Быть строгим и официальным, соблюдая субординацию.","Не вступать в личные разговоры, только по делу."]},{"id":"104460-5","text":"Кто может неожиданно зайти в бар спеть в караоке?","type":"single","options":["Звезда 90-х (иногда мы приглашаем артистов).","Известный шеф-повар из Франции.","Местный участковый инспектор"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('94440','test','Тест. Правила сотрудника РВБ','guru-43403','{"id":"94440","title":"Тест. Правила сотрудника РВБ","timeLimitSeconds":240,"passCount":8,"questions":[{"id":"94440-1","text":"Как должны пробиваться заказы, сделанные за представительским столом?","type":"multiple","options":["Все заказы пробиваются на один общий чек","Заказ руководителя пробивается на представительский стол","Остальные заказы пробиваются по обычному номеру стола, если нет другого распоряжения"]},{"id":"94440-2","text":"В каких случаях персоналу разрешено выходить на перекур в пятницу и субботу с 23:00 до 03:00?","type":"single","options":["Перекуры полностью запрещены в это время","Если официант быстро обслужил все столы","Если менеджер дал разрешение каждому сотруднику персонально","Только если в зале мало гостей"]},{"id":"94440-3","text":"Как должен поступить сотрудник, если он нашёл потерянную гостевую карту?","type":"single","options":["Воспользоваться картой для получения напитков","Вернуть её на бар","Передать карту другому гостю","Оставить карту у себя до конца смены"]},{"id":"94440-4","text":"Какие правила необходимо соблюдать при обращении к управляющему, операционному директору и генеральному директору?","type":"single","options":["Можно не соблюдать формальности в личных сообщениях","Всегда обращаться на \"Вы\"","Можно обращаться на \"Ты\", если сотрудники давно знакомы"]},{"id":"94440-5","text":"Какая скидка есть у сотрудников бара?","type":"single","options":["Скидка 50% на напитки и 30% на кальяны, покупка согласовывается с менеджером/управляющим","Скидка 40% на всё, покупка согласовывается с менеджером/управляющим в любой день","Скидка 40% на напитки и кальяны, покупка алкоголя согласовывается с менеджером/управляющим (при этом сотрудник должен быть в момент покупки на выходном).","Скидка 30% на напитки и 20% на кальяны, покупка согласовывается с менеджером/управляющим"]},{"id":"94440-6","text":"Какие из перечисленных вариантов верны о клубной карте друга?","type":"multiple","options":["Свободный вход на КВН-мероприятия на двоих","В пятницу и субботу можно пройти одному","Карта зелёно-жёлтая, номинал скидки 10%","Карта синяя, номинал скидки 10%"]},{"id":"94440-7","text":"Какие чаты должны быть закреплены в Telegram?","type":"multiple","options":["RVBteam","A3Kteam","Профильные чаты должности","Штат"]},{"id":"94440-8","text":"Какие нарушения из перечисленных могут привести к немедленному увольнению без выплаты зарплаты?","type":"multiple","options":["Угощение дам, друзей, знакомых товаром, взятым из бара, без списания по кассе","Принятие денежных переводов от гостей на личную карту","Принятие пищи и напитков в зале в зоне видимости гостей","Кража имущества бара, гостей или сотрудников","Принятие заказа с использованием телефона"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('92988','test','Тест 1. Правила работы официанта','waiter-standards','{"id":"92988","title":"Тест 1. Правила работы официанта","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"92988-1","text":"Когда официанту разрешено уйти на перекур?","type":"single","options":["Только если в зале нет гостей и все позиции закрыты","Когда хочется","В любой момент","После каждого заказа"]},{"id":"92988-2","text":"Во сколько официант должен прийти на смену, если она начинается в","type":"single","options":["20:00","19:30","19:45 (за 15 минут до начала смены)"]},{"id":"92988-3","text":"Что делать, если официант опаздывает?","type":"single","options":["Предупредить менеджера","Просто приехать в бар и начать работу","Опоздать и извиниться"]},{"id":"92988-4","text":"Как официант должен подавать блюда и напитки?","type":"single","options":["В любом порядке","Быстро, красиво и в правильной последовательности","Гость сам забирает с бара"]},{"id":"92988-5","text":"Как официант должен взаимодействовать с гостями?","type":"single","options":["Официально и сдержанно","Минимально, только принимая заказы","Как с другом, поддерживая атмосферу уюта и веселья","Исключительно по необходимости"]},{"id":"92988-6","text":"Как должен выглядеть официант?","type":"single","options":["Чистая кожа, ухоженные волосы, стильный прикид 90-х","Спортивный костюм","В строгом костюме","В любой удобной одежде"]},{"id":"92988-7","text":"Как официант должен действовать, если не знает ответа на вопрос гостя?","type":"single","options":["Сказать то, что первое придет в голову, главное - уверенно","Перевести тему","Уточнить у менеджера и вернуться с ответом"]},{"id":"92988-8","text":"Какие из этих аксессуаров допустимы для официанта на смене в \"Баре 90-е\"","type":"multiple","options":["Бандана","Клоунский нос","Резиновые сапоги","Цепь"],"optionImages":["assets/remaining-tests/b1726f8a8851814d8b980143.jpg","assets/remaining-tests/821e4e655df02744ae139b70.jpg","assets/remaining-tests/fc8601348b511860da51969e.jpg","assets/remaining-tests/a72478c84e174f56faba44a3.jpg"]},{"id":"92988-9","text":"Что из этого ты можешь надеть на смену в бар согласно правилам?","type":"multiple","options":["Значки","Костюм тройка","Костюм ростовой","Олимпийка"],"optionImages":["assets/remaining-tests/15573fefdbf2faa57e1a89cf.jpg","assets/remaining-tests/47c4f7796eaadbb9b9ac4700.jpg","assets/remaining-tests/215c38b8e08a789aaaf904aa.jpg","assets/remaining-tests/86ae450cc5f91aa1a9009e23.jpg"]},{"id":"92988-10","text":"Кто такой официант в \"Руки Вверх Бар\"?","type":"single","options":["Человек, разносящий заказы","Менеджер зала","Главный моторчик движа и создающий атмосферу 90-х","Курьер между гостем и кухней"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('92998','test','Тест 2. Открытие смены','waiter-standards','{"id":"92998","title":"Тест 2. Открытие смены","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"92998-1","text":"Как проверяется исправность терминала перед сменой?","type":"single","options":["Проверить только наличие ленты","Убедиться, что работает и есть чековая лента","Просто включить","Проверять только при необходимости"]},{"id":"92998-2","text":"Как должен выглядеть порядок в подсобке?","type":"single","options":["Проверяются только шкафчики","Обувь на полке, вещи на вешалке, ничего не валяется","Всё должно быть разложено","Проверка не требуется"]},{"id":"92998-3","text":"Что входит в обязательную проверку стейшена?","type":"single","options":["Проверка формы персонала","Терминалы и меню","Только салфетки","Полироль, тряпки, салфетки, сахар, зубочистки"]},{"id":"92998-4","text":"Какой инструмент помогает официанту держать всё под контролем при открытии смены?","type":"single","options":["Лист заказов","Чек-лист","Инструкция по безопасности","График смен"]},{"id":"92998-5","text":"Какие действия необходимо выполнить с входной группой?","type":"single","options":["Проверить ковёр","Оставить на проверку менеджеру","Проверить параметры: Чистота пола, подоконников, коврика, пепельницы, включение вентиляции","Протереть стекла"]},{"id":"92998-6","text":"Какое должно быть состояние меню при открытии зала?","type":"single","options":["Достаточно просто заменить грязные","Можно использовать даже слегка повреждённые меню","Меню не требует проверки","Чистое, без рваных страниц, протёртое влажной тряпкой"]},{"id":"92998-7","text":"Как правильно подготовить столовые приборы?","type":"single","options":["Протереть сухой тряпкой","Сложить без проверки","Ополоснуть в кипятке и натереть до блеска","Вымыть в прохладной воде"]},{"id":"92998-8","text":"Какой уровень наполнения соли и перца считается правильным?","type":"single","options":["Только если заканчивается","Полный","Наполовину","На ¾ емкости"]},{"id":"92998-9","text":"Какие элементы зала необходимо проверить перед открытием?","type":"single","options":["Пол, стулья, столы, подоконники","Только столы и салфетки","Только стулья","Только терминалы"]},{"id":"92998-10","text":"Что должно быть в идеальном порядке в гостевом туалете?","type":"single","options":["Мыло, полотенца, смыв, чистота","Только сантехника","Только чистота пола","Только наличие туалетной бумаги"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('92995','test','Тест 3. Обслуживание гостей','waiter-standards','{"id":"92995","title":"Тест 3. Обслуживание гостей","timeLimitSeconds":210,"passCount":7,"questions":[{"id":"92995-1","text":"Как официант должен заходить к гостю?","type":"single","options":["Молча, ожидая, пока гость заговорит","Без эмоций, сразу подавая меню","С улыбкой и на позитиве, создавая атмосферу 90-х","Спокойно и официально"]},{"id":"92995-2","text":"Какой приём помогает увеличить продажу блюд?","type":"single","options":["Дать гостю меню и уйти, тогда он сам закажет все, что нужно","Описание блюд с эмоциями и аппетитными деталями","Просто назвать позиции из меню, гость разберется по ходу заказа"]},{"id":"92995-3","text":"Как официант должен сообщать о времени приготовления?","type":"single","options":["Обещать минимальное время","Говорить «скоро будет»","Сообщать только если спросят","Честно сказать реальное время"]},{"id":"92995-4","text":"Что делать, если гость остался недоволен блюдом?","type":"single","options":["Ничего, гость сам разберётся","Сказать, что так и должно быть","Извиниться и уйти","Выяснить причину и предложить решение"]},{"id":"92995-5","text":"Что важно сделать при подаче меню?","type":"single","options":["Подавать открытой рукой, предложить освежающий напиток","Спросить, хочет ли гость что-то заказать сразу","Оставить на столе без слов","Подать закрытым и уйти"]},{"id":"92995-6","text":"Как правильно проводить расчёт гостя?","type":"single","options":["Только при повторном запросе","Без задержек, уточнив тип оплаты","Подождать, пока гость напомнит"]},{"id":"92995-7","text":"Как правильно делать чек-бэк?","type":"single","options":["Делать чек-бэк только в конце вечера","Спросить «Всё в порядке?» и уйти","Проявлять искренний интерес, считывать эмоции гостя","Спрашивать только, если гость выглядит недовольным"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('92993','test','Тест 4. Чек бэк','waiter-standards','{"id":"92993","title":"Тест 4. Чек бэк","timeLimitSeconds":300,"passCount":10,"questions":[{"id":"92993-1","text":"Зачем делать контрольный чек-бэк?","type":"single","options":["Сообщить об акциях","Закрепить положительное впечатление перед уходом","Уточнить сумму счета","Проверить, понравился ли официант"]},{"id":"92993-2","text":"Что такое Check Back (чек-бэк)?","type":"single","options":["Контроль за работой кухни","Проверка счета гостя","Обратная связь с гостем о качестве еды и сервиса","Оценка работы персонала"]},{"id":"92993-3","text":"Когда официант должен делать текущий чек-бэк?","type":"single","options":["Через 2-3 минуты после первой вилки еды","Перед оплатой счета","После того, как гость полностью съел блюдо","Сразу после подачи блюда"]},{"id":"92993-4","text":"Как лучше всего задавать вопросы гостю во время чек-бэка?","type":"single","options":["Ограничиваться «Всё ок?»","С искренним интересом, без шаблонных фраз","Чётко и официально","Быстро и без эмоций"]},{"id":"92993-5","text":"Что делать, если гость не в восторге от твоей рекомендации?","type":"single","options":["Переубедить его","Посоветовать что-то другое","Принять спокойно и учесть для будущих советов","Спросить, почему он выбрал это блюдо"]},{"id":"92993-6","text":"Какой стиль общения рекомендуется при чек-бэке?","type":"single","options":["Формальный и строгий","Минимальный, без эмоций","Дружеский, искренний, ненавязчивый","Только при необходимости"]},{"id":"92993-7","text":"Что делать, если гость недоволен блюдом?","type":"single","options":["Выяснить причину и сообщить менеджеру","Сказать, что так и должно быть","Извиниться и уйти","Заменить блюдо без уведомления"]},{"id":"92993-8","text":"Какой вопрос НЕ стоит задавать гостю при чек-бэке?","type":"single","options":["«Как вам наши новинки?»","«Хотите ли попробовать что-то еще?»","«Как вам блюдо?»","«Всё ли в порядке?»"]},{"id":"92993-9","text":"Когда официант делает поэтапный чек-бэк?","type":"single","options":["После выдачи чека","До подачи блюда","Когда убирает тарелку у гостя","В начале смены"]},{"id":"92993-10","text":"Что делать, если гость не доел блюдо?","type":"single","options":["Немедленно предложить другое блюдо","Спросить причину ненавязчиво","Просто забрать тарелку","Ничего не делать"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105287','test','Тест к смене 1','guru-42932','{"id":"105287","title":"Тест к смене 1","timeLimitSeconds":360,"passCount":12,"questions":[{"id":"105287-1","text":"Что отличает концепцию «Бар 90-е» от других баров?","type":"single","options":["Низкие цены на всё меню","Караоке каждый вечер","Большой выбор коктейлей","Полное погружение в эпоху 90-х: музыка, интерьер, стиль общения"]},{"id":"105287-2","text":"В какое время проводится общее собрание персонала?","type":"single","options":["17:45","17:00","18:00","18:05"]},{"id":"105287-3","text":"На какие каналы нужно подписаться в первый день стажировки?","type":"single","options":["Личные страницы управляющего","Instagram, Telegram-канал заведения и канал Операционного Директора","Только Telegram-канал заведения","Только Instagram заведения"]},{"id":"105287-4","text":"Какова цель первого дня стажировки?","type":"single","options":["Провести собрание с персоналом","Начать управлять сменой","Принять депозиты","Получить полное понимание работы заведения и ответить на вопрос «что здесь происходит вообще?»"]},{"id":"105287-5","text":"Что из перечисленного относится к техническим помещениям?","type":"single","options":["Зона хостес","Склады, раздевалка, комната персонала","Зал","Барная стойка"]},{"id":"105287-6","text":"Какая зона НЕ входит в список для ознакомления с пространством заведения в первый день?","type":"single","options":["Офис управляющего","Технические помещения","Зона хостес","Барная стойка"]},{"id":"105287-7","text":"Какие маршруты используют гости при входе в заведение?","type":"single","options":["Главный вход, гардероб, через зал к столу","Кухонный коридор","Технический выход","Служебный вход"]},{"id":"105287-8","text":"С кем нужно познакомиться на собрании в 17:00?","type":"single","options":["Только с официантами","Только с хостес","Со всей командой смены: официанты, бармены, хостес, охрана, уборщицы","Только с управляющим"]},{"id":"105287-9","text":"Какую информацию менеджер должен знать наизусть при общении с гостем?","type":"single","options":["Только адрес","Только номер телефона","Только Wi-Fi пароль","Адрес, номер телефона, Wi-Fi, часы работы"]},{"id":"105287-10","text":"Какие точки контакта с гостем существуют?","type":"single","options":["Только хостес и официант","Только встреча у стола и расчёт","Только вход и выход","Вход, гардероб, хостес, встреча у стола, приём заказа, подача, чек-бэк, расчёт, прощание, выход"]},{"id":"105287-11","text":"Какой маршрут используют сотрудники для входа в заведение?","type":"single","options":["Через гардероб","Через кухню","Через главный вход (зона суточного поста)","Через служебный вход"]},{"id":"105287-12","text":"Какая из перечисленных зон является ключевой для знакомства в первый день?","type":"single","options":["Склад хозяйственных товаров","Офис управляющего","Кабинет бухгалтера","Зона хостес"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105288','test','Тест к смене 2','guru-42932','{"id":"105288","title":"Тест к смене 2","timeLimitSeconds":600,"passCount":20,"questions":[{"id":"105288-1","text":"Кто выполняет функции гардеробщика в его отсутствие?","type":"single","options":["Бармен","Официант","Хостес","Суточный пост"]},{"id":"105288-2","text":"Какие основные функции выполняет суточный пост?","type":"single","options":["Готовит коктейли и обслуживает гостей","Принимает заказы и подаёт блюда","Убирает зал и туалеты","Контролирует время прихода/ухода персонала, досматривает сотрудников, в будни выполняет функции фейсера"]},{"id":"105288-3","text":"Что входит в обязанности гардеробщика?","type":"single","options":["Проверка броней и рассадка гостей","Приготовление напитков","Приём верхней одежды гостей, выдача номерков/браслетов, поддержание порядка","Контроль времени прихода персонала"]},{"id":"105288-4","text":"С какими таблицами работает хостес?","type":"single","options":["С таблицами бронирования, заявок и предоплат","Только с таблицей предоплат","Только с таблицей бронирования","С таблицей расходов и доходов"]},{"id":"105288-5","text":"Что должна знать хостес для работы с гостями на входе?","type":"single","options":["Схему зала, условия входа, актуальные акции, работу с предоплатами","Только схему зала","Только работу с предоплатами","Только актуальные акции"]},{"id":"105288-6","text":"Какова основная задача официанта?","type":"single","options":["Проверять бронирования","Готовить напитки","Встречать гостей, принимать заказы, подавать блюда, убирать посуду, работать с отзывами, продавать","Контролировать чистоту в туалетах"]},{"id":"105288-7","text":"Как официант взаимодействует с баром?","type":"single","options":["Официант не взаимодействует с баром","Бармен сам подаёт напитки гостям","Передаёт заказ в iiko, бармен готовит, официант забирает и подаёт","Самостоятельно готовит напитки"]},{"id":"105288-8","text":"Какое максимальное время приготовления горячих блюд?","type":"single","options":["20 минут","60 минут","40 минут","15 минут"]},{"id":"105288-9","text":"Сколько времени готовятся салаты?","type":"single","options":["15–20 минут","10–12 минут","до 7 минут","5–7 минут"]},{"id":"105288-10","text":"Какова норма времени на приготовление горячих закусок?","type":"single","options":["до 7 минут","до 20 минут","до 30 минут","до 15 минут"]},{"id":"105288-11","text":"Какое время приготовления холодных закусок?","type":"single","options":["до 15 минут","до 7 минут","20–40 минут","10–12 минут"]},{"id":"105288-12","text":"Что входит в обязанности бармена?","type":"single","options":["Базовые процессы барной станции, взаимодействие с официантами, контроль чистоты и маркировки","Работа с таблицей бронирования","Приём заказов у гостей","Уборка зала"]},{"id":"105288-13","text":"Какие зоны находятся в ответственности клининга (уборщиц)?","type":"single","options":["Только кухня","Только туалеты","Зал, туалеты, входная зона, барная стойка","Только зал"]},{"id":"105288-14","text":"Как менеджер взаимодействует с уборщицами?","type":"single","options":["Не взаимодействует, это работа суточного поста","Только проверяет туалеты","Сам убирает проблемные зоны","Ставит задачи, контролирует выполнение и качество"]},{"id":"105288-15","text":"К кому обращаться, если возник вопрос, на который менеджер смены не знает ответа?","type":"single","options":["К управляющему","К бармену","К хостес","К охране"]},{"id":"105288-16","text":"Кто подчиняется бренд-шефу?","type":"single","options":["Повара","Менеджер смены","Официанты","Бармены"]},{"id":"105288-17","text":"Кто отвечает за работу барменов по вопросам закупок и стандартов бара?","type":"single","options":["Управляющий","Шеф-повар","Менеджер смены","Бар-менеджер"]},{"id":"105288-18","text":"Какую функцию выполняет охрана в зале?","type":"single","options":["Принимает заказы","Убирает зал","Работает с бронированиями","Следит за порядком и безопасностью гостей и сотрудников, решает конфликтные ситуации"]},{"id":"105288-19","text":"Кто является главным в зале во время смены?","type":"single","options":["Менеджер смены","Шеф-повар","Управляющий","Бар-менеджер"]},{"id":"105288-20","text":"Кто контролирует чистоту барной стойки и маркировку продукции?","type":"single","options":["Хостес","Официант","Управляющий","Бармен"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105289','test','Тест к сменам 3-4','guru-42932','{"id":"105289","title":"Тест к сменам 3-4","timeLimitSeconds":540,"passCount":18,"questions":[{"id":"105289-1","text":"В какие дни обычно действует депозитная система?","type":"single","options":["Пятница, суббота, праздничные дни","Понедельник–среда","Каждый день","Только воскресенье"]},{"id":"105289-2","text":"Что такое депозит?","type":"single","options":["Скидка на напитки","Бесплатный вход","Сумма, на которую можно заказать еду, напитки, кальян","Подарок от заведения"]},{"id":"105289-3","text":"Какие три основные таблицы ведёт хостес?","type":"single","options":["Отзывы, жалобы, комплименты","Бронирования, заявки, предоплаты","Акции, мероприятия, персонал","Меню, график, расходы"]},{"id":"105289-4","text":"Какая скидка предоставляется имениннику по акции «Скидка на день рождения»?","type":"single","options":["30%","Бесплатный вход","70%","50%"]},{"id":"105289-5","text":"Что нужно предъявить для получения скидки на день рождения?","type":"single","options":["Фотографию в социальных сетях","Документ, подтверждающий дату рождения","Скидочную карту","Бронь стола"]},{"id":"105289-6","text":"В какой день действует акция «Аркадий угощает»?","type":"single","options":["Пятница","Воскресенье","Суббота","Понедельник"]},{"id":"105289-7","text":"Что получает гость по акции «Аркадий угощает»?","type":"single","options":["Бесплатный вход","Скидку 50% на весь счёт","Фишку на входе, которую обменивает на коктейль у бармена","Бесплатное караоке"]},{"id":"105289-8","text":"В какие дни действует акция «Всё меню по 390 ₽»?","type":"single","options":["Только в выходные","ПН–ЧТ, 18:00–22:00","Только в будни","ПН–ВС, весь день"]},{"id":"105289-9","text":"В какие дни и часы действует акция «Дети кушают бесплатно»?","type":"single","options":["ПН–ВС, весь день","СБ–ВС, 18:00–22:00","ПН–ЧТ, весь день","ВС–ЧТ, 18:00–22:00"]},{"id":"105289-10","text":"Какая акция работает на загрузку в будние дни и позволяет гостям петь бесплатно?","type":"single","options":["Всё меню по 390 ₽","Скидка на день рождения","Караоке за наш счёт","Аркадий угощает"]},{"id":"105289-11","text":"Какая максимальная сумма бонусов начисляется гостю с каждого посещения при золотом уровне карты?","type":"single","options":["10%","15%","5%","7%"]},{"id":"105289-12","text":"Какой максимальный процент от суммы чека гость может оплатить бонусами?","type":"single","options":["70%","30%","50%","100%"]},{"id":"105289-13","text":"Сколько бонусов получает гость при оформлении карты лояльности?","type":"single","options":["1000 рублей","500 рублей","390 рублей","100 рублей"]},{"id":"105289-14","text":"Сколько времени действуют бонусы с момента начисления?","type":"single","options":["3 месяца","1 год","6 месяцев","Бессрочно"]},{"id":"105289-15","text":"Кто имеет право закрывать стол и проводить финальный расчёт с гостем?","type":"single","options":["Только менеджер","Бармен","Старший официант","Любой официант"]},{"id":"105289-16","text":"Какое правило действует при скидке 20% и выше?","type":"single","options":["Оплата переводом на карту","Оплата только наличными","Оплата любым способом","Оплата только картой"]},{"id":"105289-17","text":"Гость хочет оплатить картой, но у него скидка 30%. Что делает менеджер?","type":"single","options":["Игнорирует правило","Принимает оплату картой","Объясняет правило: скидка 20%+ только наличными, предлагает оплатить наличными или отказаться от скидки","Зовёт официанта для расчёта"]},{"id":"105289-18","text":"На кого НЕ распространяется акция «Аркадий угощает»?","type":"single","options":["На участников квизов, конкурсов и специальных мероприятий","На гостей, которые пришли в воскресенье","На именинников","На гостей с детьми"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105290','test','Тест к сменам 5-6','guru-42932','{"id":"105290","title":"Тест к сменам 5-6","timeLimitSeconds":600,"passCount":20,"questions":[{"id":"105290-1","text":"Что такое ККД (контроль кассовой дисциплины)?","type":"single","options":["Контроль за выдачей чеков гостям","Проверка работы терминала","Ежедневная сверка всех финансовых операций (терминал, iiko, наличность)","Проверка наличия сдачи в кассе"]},{"id":"105290-2","text":"Кто имеет право закрывать стол и проводить финальный расчёт с гостем?","type":"single","options":["Любой официант","Бармен","Только менеджер","Старший официант"]},{"id":"105290-3","text":"Что происходит с несоответствиями в отчётах?","type":"single","options":["Списываются на убытки бара","Несоответствия удерживаются из зарплаты менеджера","Ничего, это нормально","Компенсируются из чаевых"]},{"id":"105290-4","text":"Что такое план-факт?","type":"single","options":["План работы на месяц","Сравнение запланированных показателей с фактическими","План продаж на день","График выхода сотрудников"]},{"id":"105290-5","text":"Какие данные нужно сверить при закрытии кассовой смены?","type":"single","options":["Терминал и наличность","iiko и наличность","Терминал, iiko и наличность","Терминал и iiko"]},{"id":"105290-6","text":"Что нужно сделать, если выручка за смену оказалась меньше плана?","type":"single","options":["Проанализировать причины (мало гостей, низкий чек, ошибки учёта)","Списать разницу на форс-мажор","Скрыть расхождение","Ничего не делать"]},{"id":"105290-7","text":"До какого числа составляется плановый график персонала?","type":"single","options":["30-го числа месяца","1-го числа месяца","25-го числа месяца","15-го числа месяца"]},{"id":"105290-8","text":"Что учитывается при составлении планового графика?","type":"single","options":["Генеральная уборка, инвентаризация, праздничные/депозитные дни, арт-программа","Только пожелания сотрудников","Только арт-программа","Только праздничные дни"]},{"id":"105290-9","text":"Как часто корректируется плановый график?","type":"single","options":["Никогда не корректируется","На основании арт-программы и при увольнении/принятии сотрудников","Раз в неделю","Ежедневно"]},{"id":"105290-10","text":"Что такое ТУРВ?","type":"single","options":["Таблица учёта рабочего времени","Техническое управление рабочим временем","Табель учёта рабочего времени","Точка учёта рабочего времени"]},{"id":"105290-11","text":"Кто контролирует корректность заполнения ТУРВ?","type":"single","options":["Менеджер","Хостес","Суточный пост","Управляющий"]},{"id":"105290-12","text":"До какого числа персонал обязан проверить свои смены в фактическом графике и расписаться?","type":"single","options":["10-го числа","5-го числа","3-го числа","1-го числа"]},{"id":"105290-13","text":"Что происходит с изменениями в табеле после 5-го числа?","type":"single","options":["Не принимаются","Принимаются только для руководителей","Принимаются с согласия управляющего","Принимаются с доплатой"]},{"id":"105290-14","text":"Какая оплата предусмотрена за продление караоке на 30 мин после закрытия?","type":"single","options":["25,000 ₽","10,000 ₽","30,000 ₽","15,000 ₽"]},{"id":"105290-15","text":"Сколько получает менеджер за 30 мин продления караоке?","type":"single","options":["2,000 ₽","1,500 ₽","2,500 ₽","1,000 ₽"]},{"id":"105290-16","text":"Что нужно сделать с чеком при покупке для бара?","type":"single","options":["Отправить менеджеру смены, он публикует в чате и подписывает «Оплачено»","Хранить у себя","Выбросить","Передать охране"]},{"id":"105290-17","text":"Что входит в ежедневный отчёт менеджера в группу «manager»?","type":"single","options":["Только график персонала","Только выручка","Только происшествия и отзывы","Выручка, расходы, чаевые, продления, мотивации, происшествия, отзывы"]},{"id":"105290-18","text":"Как отражаются чаевые артистов в отчёте?","type":"single","options":["Устно управляющему","Только в конце месяца","Каждый чек фотографируется","Не отражаются"]},{"id":"105290-19","text":"Что считается опозданием до 2 часов без согласованию?","type":"single","options":["Засчитывается как 0,7 смены","Минус полная смена","Засчитывается как 0,5 смены","Полная смена"]},{"id":"105290-20","text":"Как оплачивается уход раньше при отсутствии гостей (до 00:30)?","type":"single","options":["1 смена","0,5 смены","Не оплачивается","0,3 смены"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('105291','test','Тест к смене 7','guru-42932','{"id":"105291","title":"Тест к смене 7","timeLimitSeconds":570,"passCount":19,"questions":[{"id":"105291-1","text":"Во сколько начинается большой обход зала?","type":"single","options":["17:45","17:00","18:00","16:30"]},{"id":"105291-2","text":"Что нужно сделать с недочётами, найденными при обходе?","type":"single","options":["Проигнорировать","Сообщить только управляющему","Ничего, это не зона ответственности менеджера","Зафиксировать, озвучить на собрании, проконтролировать устранение"]},{"id":"105291-3","text":"Во сколько проводится собрание с персоналом?","type":"single","options":["17:00","17:45","18:00","17:30"]},{"id":"105291-4","text":"Что НЕ нужно озвучивать на собрании?","type":"single","options":["Итоги прошлой смены","Задачи по зонам","Акции и мероприятия","Личные оценки сотрудников"]},{"id":"105291-5","text":"Во сколько открывается заведение для гостей?","type":"single","options":["17:45","19:00","18:00","18:05"]},{"id":"105291-6","text":"Как часто нужно снимать сторис в течение смены?","type":"single","options":["Только если есть яркие моменты","Только в начале и в конце","Каждый час","Каждые 2–3 часа"]},{"id":"105291-7","text":"Что нужно сделать в 18:05?","type":"single","options":["Снять приветственное сторис","Провести собрание","Закрыть кассу","Принять выручку"]},{"id":"105291-8","text":"Как поступить, если гость жалуется на блюдо?","type":"single","options":["Сказать, что это не ваша проблема","Забрать блюдо и унести","Выслушать, поблагодарить, извиниться, позвать наставника/менеджера","Предложить скидку сразу"]},{"id":"105291-9","text":"Как часто нужно делать обход зала по малой восьмёрке?","type":"single","options":["Каждый час","Каждые 2 часа","Только в начале смены","Раз в 30 минут"]},{"id":"105291-10","text":"Что такое ОС от гостей?","type":"single","options":["Обратная связь (еда, напитки, атмосфера, сервис, арт-программа)","Остатки средств","Отчётная смена","Особые условия"]},{"id":"105291-11","text":"Что входит в закрытие смены?","type":"single","options":["Приём смены у сотрудников, заполнение графика, снятие отчётов, кассовый отчёт, обход, отчёт в «manager»","Только отчёт в «manager»","Только сдача выручки","Только приём смены у сотрудников"]},{"id":"105291-12","text":"Что нужно сделать с отчётом по смене?","type":"single","options":["Отправить в группу «manager»","Не писать, если всё хорошо","Оставить на столе","Написать лично управляющему"]},{"id":"105291-13","text":"Что входит в итоговый разбор с наставником?","type":"single","options":["Ничего, разбор не проводится","Обсуждение того, что получилось, сложностей, зон роста","Только критика","Только похвала"]},{"id":"105291-14","text":"Как нужно принимать обратную связь от наставника?","type":"single","options":["Слушать, не перебивать, не оправдываться, запомнить зоны роста","Обижаться","Спорить, доказывать свою правоту","Игнорировать"]},{"id":"105291-15","text":"Что нужно сделать с фотоотчётом чистого зала?","type":"single","options":["Отправить гостям","Удалить","Сохранить для отчёта (по регламенту)","Опубликовать в соцсетях"]},{"id":"105291-16","text":"Что является главной задачей менеджера в течение смены?","type":"single","options":["Только принимать депозиты","Организовывать работу всех подразделений, контролировать сервис и атмосферу","Самостоятельно обслуживать столы","Только снимать сторис"]},{"id":"105291-17","text":"Куда нужно сдать выручку после закрытия смены?","type":"single","options":["В сейф или инкассаторам (по регламенту)","Оставить в кассе","Управляющему домой","Отдать старшему официанту"]},{"id":"105291-18","text":"Какие часы считаются пиковыми?","type":"single","options":["03:00–06:00","18:00–21:00","23:00–03:00","21:00–23:00"]},{"id":"105291-19","text":"В какое время обрабатываются ТБ заявки?","type":"single","options":["17:00–18:00","В течение всей смены","18:00–21:00","21:00–23:00"]}]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
